function maxLengthBetweenEqualCharacters(s) {
  const first = new Map();
  let best = -1;

  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (first.has(ch)) {
      best = Math.max(best, i - first.get(ch) - 1);
    } else {
      first.set(ch, i);
    }
  }
  return best;
}

