function maxLengthBetweenEqualCharacters(s) {
  // Try every pair of positions and keep the widest gap between equal characters.
  let answer = -1;
  for (let i = 0; i < s.length; i++)
    for (let j = i + 1; j < s.length; j++)
      if (s[i] === s[j] && j - i - 1 > answer) answer = j - i - 1;
  return answer;
}

