function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const large = size === 'large';
  const n = large ? 200 + Math.floor(rand() * 101) : 1 + Math.floor(rand() * 12);
  // A small alphabet makes repeats likely; a large one (with short strings) often has none.
  const choice = rand();
  const alphabet = large ? (choice < 0.3 ? 2 + Math.floor(rand() * 5) : 26) : (choice < 0.5 ? 1 + Math.floor(rand() * 4) : 26);
  const offset = Math.floor(rand() * (27 - alphabet));
  let s = '';
  for (let i = 0; i < n; i++) s += letters[offset + Math.floor(rand() * alphabet)];
  return [s];
}
